elds[] = self::sql_sanitize($field);","                        $values[] = 'DEFAULT';","                    } else {","                        $fields[] = self::sql_sanitize($field);","                        $values[] = 'NULL';","                    }","                } else {","                    /*","                     * Campos autonumericos en Oracle deben utilizar una sequencia auxiliar","                     */","                    if ($config['type'] == 'oracle') {","                        if (!$this-\u003eid) {","                            $fields[] = 'id';","                            $values[] = $this-\u003esource.'_id_seq.NEXTVAL';","                        }","                    }","                    if ($config['type'] == 'informix') {","                        if (!$this-\u003eid) {","                            $fields[] = 'id';","                            $values[] = 0;","                        }","                    }","                }","            }","            $val = $this-\u003edb-\u003einsert($table, $values, $fields);","        }","        if (!isset($config['pdo']) \u0026\u0026 $config['type'] == 'oracle') {","            $this-\u003ecommit();","        }","        if (!$ex) {","            //$this-\u003edb-\u003elogger = true;","            $m = $this-\u003edb-\u003elast_insert_id($table, $this-\u003eprimary_key[0]);","            $this-\u003efind_first($m);","        }","        if ($val) {","            if ($ex) {","                if (method_exists($this, 'after_update')) {","                    if ($this-\u003eafter_update() == 'cancel') {","                        return false;","                    }","                } else {","                    if (isset($this-\u003eafter_update)) {","                        $method = $this-\u003eafter_update;","                        if ($this-\u003e$method() == 'cancel') {","                            return false;","                        }","                    }","                }","            }","            if (!$ex) {","                if (method_exists($this, 'after_create')) {","                    if ($this-\u003eafter_create() == 'cancel') {","                        return false;","                    }","                } else {","                    if (isset($this-\u003eafter_create)) {","                        $method = $this-\u003eafter_create;","                        if ($this-\u003e$method() == 'cancel') {","                            return false;","                        }","                    }","                }","            }","            if (method_exists($this, 'after_save')) {","                if ($this-\u003eafter_save() == 'cancel') {","                    return false;","                }","            } else {","                if (isset($this-\u003eafter_save)) {","                    $method = $this-\u003eafter_save;","                    if ($this-\u003e$method() == 'cancel') {","                        return false;","                    }","                }","            }","","            return $val;","        } else {","            return false;","        }","    }","","    /**","     * Find All data in the Relational Table.","     *","     * @param string $field","     * @param string $value","     *","     * @return ActiveRecord Cursor","     */","    public function find_all_by($field, $value)","    {","        self::sql_item_sanitize($field);","","        return $this-\u003efind(\"conditions: $field = {$this-\u003edb-\u003eadd_quotes($value) }\");","    }","","    /**","     * Updates Data in the Relational Table.","     *","     * @param mixed $values","     *","     * @return bool|null sucess","     */","    public function update()","    {","        if (func_num_args() \u003e 0) {","            $params = Util::getParams(func_get_args());","            $values = (isset($params[0]) \u0026\u0026 is_array($params[0])) ? $params[0] : $params;","            foreach ($this-\u003efields as $field) {","                if (isset($values[$field])) {","                    $this-\u003e$field = $values[$field];","                }","            }","        }","        if ($this-\u003eexists()) {","            if (method_exists($this, 'before_change')) {","                $obj = clone $this;","                if ($this-\u003ebefore_change($obj-\u003efind($this-\u003e{$this-\u003eprimary_key[0]})) == 'cancel') {","                    return false;","                }","                unset($obj);","            }","            if ($this-\u003esave()) {","                if (method_exists($this, 'after_change')) {","                    if ($this-\u003eafter_change($this) == 'cancel') {","                        return false;","                    }","                }","","                return true;","            }","        } else {","            Flash::error('No se puede actualizar porque el registro no existe');","","            return false;","        }","    }","","    /**","     * Deletes data from Relational Map Table.","     *","     * @param mixed $what","     */","    public function delete($what = '')","    {","        if (func_num_args() \u003e 1) {","            $what = Util::getParams(func_get_args());","        }","        if ($this-\u003eschema) {","            $table = $this-\u003eschema.'.'.$this-\u003esource;","        } else {","            $table = $this-\u003esource;","        }","        $conditions = '';","        if (is_array($what)) {","            if ($what['conditions']) {","                $conditions = $what['conditions'];","            }","        } else {","            if (is_numeric($what)) {","                self::sql_sanitize($this-\u003eprimary_key[0]);","                $conditions = \"{$this-\u003eprimary_key[0]} = '$what'\";","            } else {","                if ($what) {","                    $conditions = $what;","                } else {","                    self::sql_sanitize($this-\u003eprimary_key[0]);","                    $conditions = \"{$this-\u003eprimary_key[0]} = '{$this-\u003e{$this-\u003eprimary_key[0]}}'\";","                }","            }","        }","        if (method_exists($this, 'before_delete')) {","            if ($this-\u003e{$this-\u003eprimary_key[0]}) {","                $this-\u003efind($this-\u003e{$this-\u003eprimary_key[0]});","            }","            if ($this-\u003ebefore_delete() == 'cancel') {","                return false;","            }","        } else {","            if (isset($this-\u003ebefore_delete)) {","                if ($this-\u003e{$this-\u003eprimary_key[0]}) {","                    $this-\u003efind($this-\u003e{$this-\u003eprimary_key[0]});","                }","                $method = $this-\u003ebefore_delete;","                if ($this-\u003e$method() == 'cancel') {","                    return false;","                }","            }","        }","        $val = $this-\u003edb-\u003edelete($table, $conditions);","        if ($val) {","            if (method_exists($this, 'after_delete')) {","                if ($this-\u003eafter_delete() == 'cancel') {","                    return false;","                }","            } else {","                if (isset($this-\u003eafter_delete)) {","                    $method = $this-\u003eafter_delete;","                    if ($this-\u003e$method() == 'cancel') {","                        return false;","                    }","                }","            }","        }","","        return $val;","    }","","    /**","     * Actualiza todos los atributos de la entidad","     * $Clientes-\u003eupdate_all(\"estado='A', fecha='2005-02-02'\", \"id\u003e100\");","     * $Clientes-\u003eupdate_all(\"estado='A', fecha='2005-02-02'\", \"id\u003e100\", \"limit: 10\");.","     *","     * @param string $values","     */","    public function update_all($values)","    {","        $params = array();","        if ($this-\u003eschema) {","            $table = $this-\u003eschema.'.'.$this-\u003esource;","        } else {","            $table = $this-\u003esource;","        }","        if (func_num_args() \u003e 1) {","            $params = Util::getParams(func_get_args());","        }","        if (!isset($params['conditions']) || !$params['conditions']) {","            if (isset($params[1])) {","                $params['conditions'] = $params[1];","            } else {","                $params['conditions'] = '';","            }","        }","        if ($params['conditions']) {","            $params['conditions'] = ' WHERE '.$params['conditions'];","        }","        $sql = \"UPDATE $table SET $values {$params['conditions']}\";","        $limit_args = array($sql);","        if (isset($params['limit'])) {","            array_push($limit_args, \"limit: $params[limit]\");","        }","        if (isset($params['offset'])) {","            array_push($limit_args, \"offset: $params[offset]\");","        }","        if (count($limit_args) \u003e 1) {","            $sql = call_user_func_array(array($this, 'limit'), $limit_args);","        }","        $environment = Config::read('databases');","        $config = $environment[$this-\u003eget_database()];","        if (!isset($config-\u003epdo) || !$config-\u003epdo) {","            if ($config['type'] == 'informix') {","                $this-\u003edb-\u003eset_return_rows(false);","            }","        }","","        return $this-\u003edb-\u003equery($sql);","    }","","    /**","     * Delete All data from Relational Map Table.","     *","     * @param string $conditions","     *","     * @return bool","     */","    public function delete_all($conditions = '')","    {","        //$limit = '';","        if ($this-\u003eschema) {","            $table = $this-\u003eschema.'.'.$this-\u003esource;","        } else {","            $table = $this-\u003esource;","        }","        if (func_num_args() \u003e 1) {","            $params = Util::getParams(func_get_args());","            $limit_args = array();","            if (isset($params['limit'])) {","                array_push($limit_args, \"limit: $params[limit]\");","            }","            if (isset($params['offset'])) {","                array_push($limit_args, \"offset: $params[offset]\");","            }","            if (count($limit_args) \u003e 1) {","                $select = call_user_func_array(array($this, 'limit'), $limit_args);","            }","        }","","        return $this-\u003edb-\u003edelete($table, $conditions);","    }","","    /**","     * *********************************************************************************","     * Metodos de Debug","     * *********************************************************************************.","     */","","    /**","     * Imprime una version humana de los valores de los campos","     * del modelo en una sola linea.","     */","    public function inspect()","    {","        $inspect = array();","        foreach ($this-\u003efields as $field) {","            if (!is_array($field)) {","                $inspect[] = \"$field: {$this-\u003e$field}\";","            }","        }","","        return join(', ', $inspect);","    }","","    /**","     * *********************************************************************************","     * Metodos de Validacion","     * *********************************************************************************.","     */","","    /**","     * Valida que el campo no sea nulo.","     *","     * @param string $field  campo a validar","     * @param array  $params parametros adicionales","     *","     * message: mensaje a mostrar","     * field: nombre de campo a mostrar en el mensaje","     */","    protected function validates_presence_of($field, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['presence_of'][$field] = $params;","    }","","    /**","     * Valida el tamañoo de ciertos campos antes de insertar","     * o actualizar.","     *","     * @params string $field campo a validar","     *","     * @param int   $max    valor maximo","     * @param int   $min    valor minimo","     * @param array $params parametros adicionales","     *","     * too_short: mensaje a mostrar cuando se muy corto","     * too_long: mensaje a mostrar cuando sea muy largo","     * field: nombre de campo a mostrar en el mensaje","     */","    protected function validates_length_of($field, $max, $min = 0, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['length_of'][$field] = $params;","        $this-\u003e_validates['length_of'][$field]['min'] = $min;","        $this-\u003e_validates['length_of'][$field]['max'] = $max;","    }","","    /**","     * Valida que el campo se encuentre entre los valores de una lista","     * antes de insertar o actualizar.","     *","     * @param string $field campo a validar","     * @param array  $list","     *","     * message: mensaje a mostrar","     * field: nombre del campo a mostrar en el mensaje","     */","    protected function validates_inclusion_in($field, $list, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['inclusion_in'][$field] = $params;","        $this-\u003e_validates['inclusion_in'][$field]['list'] = $list;","    }","","    /**","     * Valida que el campo no se encuentre entre los valores de una lista","     * antes de insertar o actualizar.","     *","     * @param string $field campo a validar","     * @param array  $list","     *","     * message: mensaje a mostrar","     * field: nombre del campo a mostrar en el mensaje","     */","    protected function validates_exclusion_of($field, $list, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['exclusion_of'][$field] = $params;","        $this-\u003e_validates['exclusion_of'][$field]['list'] = $list;","    }","","    /**","     * Valida que el campo tenga determinado formato segun una expresion regular","     * antes de insertar o actualizar.","     *","     * @param string $field   campo a validar","     * @param string $pattern expresion regular para preg_match","     *","     * message: mensaje a mostrar","     * field: nombre del campo a mostrar en el mensaje","     */","    protected function validates_format_of($field, $pattern, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['format_of'][$field] = $params;","        $this-\u003e_validates['format_of'][$field]['pattern'] = $pattern;","    }","","    /**","     * Valida que ciertos atributos tengan un valor numerico","     * antes de insertar o actualizar.","     *","     * @param string $field campo a validar","     *","     * message: mensaje a mostrar","     * field: nombre del campo a mostrar en el mensaje","     */","    protected function validates_numericality_of($field, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['numericality_of'][$field] = $params;","    }","","    /**","     * Valida que ciertos atributos tengan un formato de e-mail correcto","     * antes de insertar o actualizar.","     *","     * @param string $field campo a validar","     *","     * message: mensaje a mostrar","     * field: nombre del campo a mostrar en el mensaje","     */","    protected function validates_email_in($field, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['email_in'][$field] = $params;","    }","","    /**","     * Valida que ciertos atributos tengan un valor unico antes","     * de insertar o actualizar.","     *","     * @param string $field campo a validar","     *","     * message: mensaje a mostrar","     * field: nombre del campo a mostrar en el mensaje","     */","    protected function validates_uniqueness_of($field, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['uniqueness_of'][$field] = $params;","    }","","    /**","     * Valida que ciertos atributos tengan un formato de fecha acorde al indicado en","     * config/config.ini antes de insertar o actualizar.","     *","     * @param string $field campo a validar","     *","     * message: mensaje a mostrar","     * field: nombre del campo a mostrar en el mensaje","     */","    protected function validates_date_in($field, $params = array())","    {","        if (is_string($params)) {","            $params = Util::getParams(func_get_args());","        }","        $this-\u003e_validates['date_in'][$field] = $params;","    }","","    /**","     * Verifica si un campo es de tipo de dato númerico o no.","     *","     * @param string $field","     *","     * @return bool","     */","    public function is_a_numeric_type($field)","    {","        return (strpos(' '.$this-\u003e_data_type[$field], 'int') || strpos(' '.$this-\u003e_data_type[$field], 'decimal') || strpos(' '.$this-\u003e_data_type[$field], 'number'));","    }","","    /**","     * Obtiene los datos de los metadatos generados por Primera vez en la Sesión.","     *","     * @param string $table","     *","     * @return array","     */","    public static function get_meta_data($table)","    {","        if (isset(self::$models[$table])) {","            return self::$models[$table];","        }","        if (PRODUCTION) {","            $metadata = Cache::driver()-\u003eget($table, 'kumbia.models');","            if ($metadata) {","                return self::$models[$table] = unserialize($metadata);","            }","        }","","        return array();","    }","","    /**","     * Crea un registro de meta datos para la tabla especificada.","     *","     * @param string $table","     * @param array  $meta_data","     */","    public static function set_meta_data($table, $meta_data)","    {","        if (PRODUCTION) {","            Cache::driver()-\u003esave(serialize($meta_data), Config::get('config.application.metadata_lifetime'), $table, 'kumbia.models');","        }","        self::$models[$table] = $meta_data;","","        return true;","    }","","    /** ******************************************************************************************","     * Métodos para generación de relaciones.","     * ***************************************************************************************** */","","    /**","     * Crea una relacion 1-1 entre dos modelos.","     *","     * @param string $relation","     *","     * model : nombre del modelo al que se refiere","     * fk : campo por el cual se relaciona (llave foranea)","     */","    protected function has_one($relation)","    {","        $params = Util::getParams(func_get_args());","        for ($i = 0; isset($params[$i]); ++$i) {","            $relation = Util::smallcase($params[$i]);","            $index = explode('/', $relation);","            $index = end($index);","            if (!array_key_exists($index, $this-\u003e_has_one)) {","                $this-\u003e_has_one[$index] = new stdClass();","                $this-\u003e_has_one[$index]-\u003emodel = isset($params['model']) ? $params['model'] : $relation;","                $this-\u003e_has_one[$index]-\u003efk = isset($params['fk']) ? $params['fk'] : Util::smallcase(get_class($this)).'_id';","            }","        }","    }","","    /**","     * Crea una relacion 1-1 inversa entre dos modelos.","     *","     * @param string $relation","     *","     * model : nombre del modelo al que se refiere","     * fk : campo por el cual se relaciona (llave foranea)","     */","    protected function belongs_to($relation)","    {","        $params = Util::getParams(func_get_args());","        for ($i = 0; isset($params[$i]); ++$i) {","            $relation = Util::smallcase($params[$i]);","            $index = explode('/', $relation);","            $index = end($index);","            if (!array_key_exists($index, $this-\u003e_belongs_to)) {","                $this-\u003e_belongs_to[$index] = new stdClass();","                $this-\u003e_belongs_to[$index]-\u003emodel = isset($params['model']) ? $params['model'] : $relation;","                $this-\u003e_belongs_to[$index]-\u003efk = isset($params['fk']) ? $params['fk'] : \"{$relation}_id\";","            }","        }","    }","","    /**","     * Crea una relacion 1-n entre dos modelos.","     *","     * @param string $relation","     *","     * model : nombre del modelo al que se refiere","     * fk : campo por el cual se relaciona (llave foranea)","     */","    protected function has_many($relation)","    {","        $params = Util::getParams(func_get_args());","        for ($i = 0; isset($params[$i]); ++$i) {","            $relation = Util::smallcase($params[$i]);","            $index = explode('/', $relation);","            $index = end($index);","            if (!array_key_exists($index, $this-\u003e_has_many)) {","                $this-\u003e_has_many[$index] = new stdClass();","                $this-\u003e_has_many[$index]-\u003emodel = isset($params['model']) ? $params['model'] : $relation;","                $this-\u003e_has_many[$index]-\u003efk = isset($params['fk']) ? $params['fk'] : Util::smallcase(get_class($this)).'_id';","            }","        }","    }","","    /**","     * Crea una relación n-n o 1-n inversa entre dos modelos.","     *","     * @param string $relation","     *","     * model : nombre del modelo al que se refiere","     * fk : campo por el cual se relaciona (llave foranea)","     * key: campo llave que identifica al propio modelo","     * through : através de que tabla","     */","    protected function has_and_belongs_to_many($relation)","    {","        $params = Util::getParams(func_get_args());","        for ($i = 0; isset($params[$i]); ++$i) {","            $relation = Util::smallcase($params[$i]);","            if (!array_key_exists($relation, $this-\u003e_has_and_belongs_to_many)) {","                $this-\u003e_has_and_belongs_to_many[$relation] = new stdClass();","                $this-\u003e_has_and_belongs_to_many[$relation]-\u003emodel = isset($params['model']) ? $params['model'] : $relation;","                $this-\u003e_has_and_belongs_to_many[$relation]-\u003efk = isset($params['fk']) ? $params['fk'] : \"{$relation}_id\";","                $this-\u003e_has_and_belongs_to_many[$relation]-\u003ekey = isset($params['key']) ? $params['key'] : Util::smallcase(get_class($this)).'_id';","                if (isset($params['through'])) {","                    $this-\u003e_has_and_belongs_to_many[$relation]-\u003ethrough = $params['through'];","                }","            }","        }","    }","","    /**","     * Herencia Simple.","     */","","    /**","     * Especifica que la clase es padre de otra.","     *","     * @param string $parent","     */","    public function parent_of($parent)","    {","        $parents = func_get_args();","        foreach ($parents as $parent) {","            if (!in_array($parent, $this-\u003eparent_of)) {","                $this-\u003eparent_of[] = $parent;","            }","        }","    }","","    /**","     * Elimina caracteres que podrian ayudar a ejecutar","     * un ataque de Inyeccion SQL.","     *","     * @param string $sql_item","     */","    public static function sql_item_sanitize($sql_item)","    {","        $sql_item = trim($sql_item);","        if ($sql_item !== '' \u0026\u0026 $sql_item !== null) {","            $sql_temp = preg_replace('/\\s+/', '', $sql_item);","            if (!preg_match('/^[a-zA-Z0-9_\\.]+$/', $sql_temp)) {","                throw new KumbiaException('Se está tratando de ejecutar un SQL peligroso!');","            }","        }","","        return $sql_item;","    }","","    /**","     * Elimina caracteres que podrian ayudar a ejecutar","     * un ataque de Inyeccion SQL.","     *","     * @param string $sql_item","     */","    public static function sql_sanitize($sql_item)","    {","        $sql_item = trim($sql_item);","        if ($sql_item !== '' \u0026\u0026 $sql_item !== null) {","            $sql_temp = preg_replace('/\\s+/', '', $sql_item);","            if (!preg_match('/^[a-zA-Z_0-9\\,\\(\\)\\.\\*]+$/', $sql_temp)) {","                throw new KumbiaException('Se está tratando de ejecutar un SQL peligroso!');","            }","        }","","        return $sql_item;","    }","","    /**","     * Al sobreescribir este metodo se puede controlar las excepciones de un modelo.","     *","     * @param unknown_type $e","     */","    protected function exceptions($e)","    {","        throw $e;","    }","","    /**","     * Implementacion de __toString Standard.","     */","    public function __toString()","    {","        return '\u003c'.get_class($this).' Object\u003e';","    }","","    /**","     * Paginador para el modelo.","     *","     * conditions: condiciones para paginacion","     * page: numero de pagina a mostrar (por defecto la pagina 1)","     * per_page: cantidad de elementos por pagina (por defecto 10 items por pagina)","     *","     * @return un objeto Page identico al que se regresa con el util paginate","     */","    public function paginate()","    {","        $args = func_get_args();","        array_unshift($args, $this);","        //if(!class_exists('Paginator')){","        require_once CORE_PATH.'libs/kumbia_active_record/behaviors/paginate.php';","        //}","        return call_user_func_array(array('Paginator', 'paginate'), $args);","    }","","    /**","     * Paginador para el modelo atraves de consulta sql.","     *","     * @param string $sql consulta sql","     *","     * page: numero de pagina a mostrar (por defecto la pagina 1)","     * per_page: cantidad de elementos por pagina (por defecto 10 items por pagina)","     *","     * @return un objeto Page identico al que se regresa con el util paginate_by_sql","     */","    public function paginate_by_sql($sql)","    {","        $args = func_get_args();","        array_unshift($args, $this);","        //if(!class_exists('Paginator')){","        require_once CORE_PATH.'libs/kumbia_active_record/behaviors/paginate.php';","        //}","        return call_user_func_array(array('Paginator', 'paginate_by_sql'), $args);","    }","","    /**","     * Operaciones al serializar.","     *","     * */","    public function __sleep()","    {","        /*","         * Anulando conexion a bd en el modelo","         * */","        $this-\u003edb = null;","","        return array_keys(get_object_vars($this));","    }","","    /**","     * Operaciones al deserializar.","     *","     * */","    public function __wakeup()","    {","        /*","         * Restableciendo conexion a la bd","         * */","        $this-\u003e_connect();","    }","","    /**","     * Obtiene la instacia de un modelo.","     *","     * @param string $model","     *","     * @return ActiveRecord","     * @throw KumbiaException","     * */","    public static function get($model)","    {","        /**","         * Nombre de la clase.","         * */","        $Model = Util::camelcase($model);","","        return new $Model();","    }","","    /**","     * Devuelve un JSON de este modelo.","     *","     * @return string JSON del modelo","     */","    public function to_json()","    {","        return json_encode($this);","    }","","    /**","     * Devuelve un array de este modelo.","     *","     * @return array Array del modelo","     */","    public function to_array()","    {","        return (array) $this;","    }","","    /**","     * Devuelve un PHP serial de este modelo","     * Usarlo con cuidado, ya que pasa todos los atributos, no sólo los publicos.","     *","     * @return string Serial de PHP del modelo","     */","    public function serialize()","    {","        return serialize($this);","    }","}"],"stylingDirectives":null,"colorizedLines":["\u003cspan class=pl-ent\u003e\u0026lt;?php\u003c/span\u003e","\u003cspan class=pl-c\u003e/**\u003c/span\u003e","\u003cspan class=pl-c\u003e * KumbiaPHP web \u0026amp; app Framework\u003c/span\u003e","\u003cspan class=pl-c\u003e *\u003c/span\u003e","\u003cspan class=pl-c\u003e * LICENSE\u003c/span\u003e","\u003cspan class=pl-c\u003e *\u003c/span\u003e","\u003cspan class=pl-c\u003e * This source file is subject to the new BSD license that is bundled\u003c/span\u003e","\u003cspan class=pl-c\u003e * with this package in the file LICENSE.\u003c/span\u003e","\u003cspan class=pl-c\u003e *\u003c/span\u003e","\u003cspan class=pl-c\u003e * @category   Kumbia\u003c/span\u003e","\u003cspan class=pl-c\u003e * @package    ActiveRecord\u003c/span\u003e","\u003cspan class=pl-c\u003e *\u003c/span\u003e","\u003cspan class=pl-c\u003e * @copyright  Copyright (c) 2005 - 2023 KumbiaPHP Team (http://www.kumbiaphp.com)\u003c/span\u003e","\u003cspan class=pl-c\u003e * @license    https://github.com/KumbiaPHP/KumbiaPHP/blob/master/LICENSE   New BSD License\u003c/span\u003e","\u003cspan class=pl-c\u003e */\u003c/span\u003e","\u003cspan class=pl-c\u003e/**\u003c/span\u003e","\u003cspan class=pl-c\u003e * @see Db\u003c/span\u003e","\u003cspan class=pl-c\u003e */\u003c/span\u003e","\u003cspan class=pl-k\u003erequire\u003c/span\u003e \u003cspan class=pl-c1\u003eCORE_PATH\u003c/span\u003e.\u003cspan class=pl-s\u003e\u0026#39;\u003cspan class=pl-s\u003elibs/db/db.php\u003c/span\u003e\u0026#39;\u003c/span\u003e;","","\u003cspan class=pl-c\u003e/**\u003c/span\u003e","\u003cspan class=pl-c\